INSERT INTO `creature_text` (`CreatureID`,`GroupID`,`ID`,`Text`,`Type`,`Language`,`Probability`,`Emote`,`Duration`,`Sound`,`BroadcastTextId`,`TextRange`,`comment`) VALUES
(77209,0,0,'Благодаря тебе у нас появился отличный форпост в Долине Призрачной Луны.',12,0,100.0,396,0,0,0,0,'Барос Алекстон to Player'),
(77209,1,0,'Может, на корабле орков найдется что-нибудь полезное?.. Кроме этих сверл для зубов.',12,0,100.0,1,0,0,0,0,'Барос Алекстон to Player'),
(77209,2,0,'Уф. Может, сегодня мне даже удастся полюбоваться на звезды. Смена обстановки не помешает.',12,0,100.0,4,0,0,0,0,'Барос Алекстон to Player'),
(77209,3,0,'Фу, некоторые припасы совсем промокли и... какие-то липкие. Можно использовать, но выглядят они мерзко.',12,0,100.0,1,0,0,0,0,'Барос Алекстон to Player'),
(77209,4,0,'Казармы мы мигом построим. Командир, следуй за мной.',12,0,100.0,0,0,0,0,0,'Барос Алекстон to Player'),
(77209,5,0,'Строительство других зданий займет гораздо больше времени.',12,0,100.0,0,0,0,0,0,'Барос Алекстон to Player'),
(77209,6,0,'Прими работу, когда пожелаешь.',12,0,100.0,0,0,0,0,0,'Барос Алекстон to Player'),
(77209,7,0,'Казармы выглядят превосходно. Поговори с Мараадом, а я пока полюбуюсь своей искусной работой.',12,0,100.0,0,0,0,0,0,'Барос Алекстон to Player'),
(78466,0,0,'Большинство зданий строится только со временем. Раз уж это ваша первая постройка, я все устрою и попрошу старшего батрака нам подсобить.',12,0,100.0,0,0,0,0,0,'Газлоу to Player'),
(78466,1,0,'Если найдешь еще чертежи и материалы, приноси их мне, и мы застроим другие участки.',12,0,100.0,0,0,0,0,0,'Газлоу to Player'),
(78466,2,0,'Резлак тоже постарается добыть кое-какие чертежи, которые ты сможешь получить... за отдельную плату.',12,0,100.0,0,0,0,0,0,'Газлоу to Player'),
(80223,0,0,'Не забудь потом как-нибудь снова заглянуть за ресурсами, командир. Во время твоего отсутствия батраки будут складывать все вот в этот сундук.',12,0,100.0,1,0,0,0,0,'Леди Сена to Player'),
(80225,0,0,'Ну вот и все! Армия полностью вооруженных и воодушевленных батраков принимается за дело.',12,0,100.0,0,0,0,0,0,'Скеггит to Player'),
(81441,0,0,'������� ����, ���� ���������� � �������� ���������. � ���� ������� ��������, ������ ���... ���� ��������� ������ ��� ������� ��������.',12,0,100.0,0,0,0,0,0,'����� ����� to Player'),
(84455,0,0,'���, �����, ������� ����������.',12,0,100.0,0,0,0,0,0,'��������� ����� ������ to Player');
